+const menuToggle = document.querySelector(".menu-toggle");
+const navPanel = document.querySelector(".nav-panel");
+const menuLabel = menuToggle?.querySelector(".sr-only");
+
+if (menuToggle && navPanel && menuLabel) {
+  menuToggle.addEventListener("click", () => {
+    const isOpen = menuToggle.getAttribute("aria-expanded") === "true";
+    menuToggle.setAttribute("aria-expanded", String(!isOpen));
+    menuLabel.textContent = isOpen ? "Open navigation menu" : "Close navigation menu";
+    navPanel.classList.toggle("is-open", !isOpen);
+    document.body.classList.toggle("menu-open", !isOpen);
+  });
+
+  navPanel.addEventListener("click", (event) => {
+    const target = event.target;
+
+    if (target instanceof HTMLAnchorElement) {
+      menuToggle.setAttribute("aria-expanded", "false");
+      menuLabel.textContent = "Open navigation menu";
+      navPanel.classList.remove("is-open");
+      document.body.classList.remove("menu-open");
+    }
+  });
+}
+
+document.querySelectorAll("[data-product]").forEach((button) => {
+  button.addEventListener("click", () => {
+    const productName = button.getAttribute("data-product");
+    button.textContent = productName ? `${productName} added` : "Added to cart";
+    button.setAttribute("aria-live", "polite");
+  });
+});
+
+const signupForm = document.querySelector(".signup-form");
+const formMessage = document.querySelector(".form-message");
+
+if (signupForm && formMessage) {
+  signupForm.addEventListener("submit", (event) => {
+    event.preventDefault();
+    const formData = new FormData(signupForm);
+    const email = String(formData.get("email") || "").trim();
+
+    if (!email) {
+      formMessage.textContent = "Enter an email address to join.";
+      return;
+    }
+
+    formMessage.textContent = "Thanks. You are on the early-access list.";
+    signupForm.reset();
